class Solution:
    def parse_s_r(ar:list) -> tuple: 
        S = defaultdict(list)
        R = defaultdict(list)
        for s in ar: 
            if s[0] == s[1]:
                R[s].append(s[0])
            else:
                S[s[0]].append(s[0])
                R[s[0]].append(s[1])
        return tuple(S.items()), tuple(R.items())

    def solve(self, ar: list) -> None:
        q,k = len(ar),0
        S, R = self.parse_s_r(ar)
        return [q, sum(len(R[y])+len(R[y])!=0+X) for x,y in S + R]
