    if i == n:
        return 1

    if memo[i, col] != -1:
        return memo[i, col]

    res = 0
    if grid[i] == '?' and col % 2 == 0:
        col_inc = 'B'
        ren = 0
    else:
        col_inc = 'W'
        ren = 1
    if grid[i] == '?' and col % 2 == 0:
        res += dfs(i + 1, col + 1, grid) % 998244353
    elif (col + 1) % 2 == 0:
        if ren:
            for j in range(n):
                if j != i and grid[j] != '?':
                    if grid[j] == grid[i] or grid[j] == col + 1:
                        res += dfs(i + 1, col, grid) % 998244353
        else:
            for j in range(n):
                if j != i and grid[j] != '?':
                    if grid[j] == grid[i] or grid[j] == col:
                        res += dfs(i + 1, col, grid) % 998244353

    else:
        for j in range(n):
            if j != i and grid[j] != '?':
                if grid[j] == grid[i] or grid[j] == col:
                    res += dfs(i + 1, col, grid) % 998244353

