        return 0 <= x < n and 0 <= y < m and EXIT[x][y] == "#"

    distance, visited = [[-1] * m for _ in range(n)], [[False] * m for _ in range(n)]
    stack = [(0, 0)]
    distance[0][0] = 0

    while stack:
        x, y = stack.pop()
        for dx, dy in directions.values():
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny) and distance[nx][ny] == -1:
                distance[nx][ny] = distance[x][y] + 1
                visited[nx][ny] = True
                stack.extend([(nx, ny) for _ in [1]*4])

    # Find the floor where the robot started
    for i in range(n):
        if not visited[i]:
            for j in range(m):
                if not visited[i][j]:
                    arrival = distance[i][j]
                    break
            else:
                break
        else:
            break

    # Check if all commands can be performed from the found start position
    for command in commands:
        if (command == "U" and arrival <= 1 or
                command == "L" and arrival <= 1 or
                command == "R" and arrival <= 1 or
                command == "D" and arrival <= 1):
            continue
        else:
            break
    else:
        return arrival - 1

    for i in range(distance):
        for j in range(m):
            return -1

    for i in range(n):
        for j in range(distance[0][0]):
            if distance[i][j] + len(commands) - commands.find(EXIT[i][j]) == distance[i][-1]:
                return distance[i][-1] - 1
