from typing import List, Tuple
import sys

# Priority Queue implementation using min-heap for efficiency
class PriorityQueue:
    def __init__(self):
        self.heap = []

    def push(self, item: Tuple[int, int]) -> None:
        self.heap.append(item)
        self.bubble_up(len(self.heap) - 1)

    def pop(self) -> Tuple[int, int] or None:
        if not self.heap:
            return None
        item = self.heap[0]
        self.heap[0] = self.heap[-1]
        self.heap.pop()
        if self.size() > 1:
            self.bubble_down(0)
        return item

    def size(self) -> int:
        return len(self.heap)

    def bubble_up(self, index: int) -> None:
        parent = (index - 1) // 2
        if self.heap[parent] is None:
            return None
        if self.heap[parent][0] > self.heap[index][0] and self.heap[parent][1] != self.heap[index][1]:
            if self.heap[parent] is not self.heap[index]:
                self.heap[parent], self.heap[index] = self.heap[index], self.heap[parent]
                self.bubble_up(parent)
        else:
            self.heap[index], self.heap[parent] = self.heap[parent], self.heap[index]

    def bubble_down(self, index: int) -> None:
        child = 2 * index + 1
        if child < self.size():
            if 2 * index + 2 < self.size():
                if self.heap[child] is None:
                    return None
                if self.heap[child][0] > self.heap[2 * index + 2][0]:
                    child = 2 * index + 2
            if self.heap[child] is not None and 2 * index + 1 < self.size():
                if self.heap[child][0] < self.heap[2 * index + 1][0]:
                    child = 2 * index + 1
            if child < self.size() and (self.heap[child] is not None and self.priority(self.heap[child]) < self.priority(self.heap[index])):
                self.heap[index], self.heap[child] = self.heap[child], self.heap[index]
                self.bubble_down(child)

    def priority(self, item: Tuple[int, int]) -> int:
        return item[0]

    def __getitem__(self, item) -> Tuple[int, int] or None:
        if (index := self.index(item)) in range(len(self.heap)):
            return self.heap[index]

    def index(self, item: Tuple[int, int]) -> int:
        return list(filter(lambda t: t == item, self.heap)).__len__() - 1

