from collections import deque

class TreeMap:
    def __init__(self):
        self.tree_map = {}

    def insert(self, x, y):
        self.tree_map[(x, y)] = True

    def erase(self, x, y):
        if (x, y) in self.tree_map:
            del self.tree_map[(x, y)]

    def check_extend(self):
        extend_count = 0
        extend_set = deque()

        for coord, exists in self.tree_map.items():
            if exists:
                extend_count += 1
                extend_set.append(coord)

        while True:
            x1, y1 = extend_set[0]
            if not extend_set:
                break

            x2, y2 = extend_set[0]
            if x2 != x1:
                continue

            extend_set.popleft()
            if self.tree_map.get((x1, y2)):
                break

            del self.tree_map[(x1, y1)]
            # insert the path (x2, x2) to extend the set
            extend_set.insert(0, (x1, x2))
            extend_count += 1

        return extend_count

