from collections import deque

def game_winner(battlefield, n, m, k):
    q = deque()

    for i in range(n):
        for j in range(m):
            if battlefield[i][j] == "G":
                q.append((i, j))
            elif battlefield[i][j] == "R":
                q.append((i, j))

    while q:
        for _ in range(min(len(q), k) + 1):
            i, j = q.popleft()
            if i + 1 < n and battlefield[i + 1][j] % 2:
                battlefield[i + 1][j] += 1
                q.append((i + 1, j))
            if i - 1 >= 0 and battlefield[i - 1][j] % 2:
                battlefield[i - 1][j] += 1
                q.append((i - 1, j))
            if j + 1 < m and battlefield[i][j + 1] % 2:
                battlefield[i][j + 1] += 1
                q.append((i, j + 1))
            if j - 1 >= 0 and battlefield[i][j - 1] % 2:
                battlefield[i][j - 1] += 1
                q.append((i, j - 1))

    return "First" if any(battlefield[i][j] % 2 for i in range(n) for j in range(m)) or (k is not None and len([char for char in (char for char in '0' if char in ('-', 'G', 'R')), char is None])) else "Second"

