    first_row_permutations = []
    for i in range(1, n + 1):
        row = list(range(1, n + 1))
        first_row_permutations.append(first_row_permutations := row)

    # Generate beautiful matrices by combining first row with d-paths.
    for k in range(1, n):
        dp = [0] + dp + [k + 1]

    return sum((1 << i // n) * dp[i % n] for i in nth_combinations(range(1, 4), n))

def nduple(xs):
    xs = list(xs) + [0]
    for i in range(1, len(xs)):
        yield xs[i-1], xs[i]

def nth_combinations(n, k, indexes=[], step=1):
    if k > len(indexes) - n:
        yield tuple(indexes + [0] * len(indexes))
        return

    for sizes in nduple(generate_permutations(n, k)):
        subtract_index = 0
        for index, size in sizes:
            if subtract_index == len(indexes):
                indexes.append(index)
                break

            for _ in range(size):
                indexes[subtract_index] = index
                nth_combinations(subtract_index + 1, k - 1, indexes, step)
            subtract_index += 1

def generate_permutations(n, k):
    if k == 0:
        yield list(range(1, n + 1))
        yield []
        return

    for i in nth_permutations(n + k):
        for j in ndtuple(i):
            yield j
    else:
        for j in ndtuple(i[0][:k]):            
            i[0].append(1)
            gen = generate_permutations(n, k - 1)
            for l in gen:
                yield l
            yield ([0] * k + [1], )            
            i[0].pop()
        yield []


