def count_ways(n: int, dominoes: List[str]) -> int:
    MOD = 998244353

    def dp(i, has_w, mask, right, prev):
        if i == n:
            return 1
        if mask in memo:
            return memo[mask]

        result = 0
        if right == '?' and has_w != right:
            right ^= has_w
            result = (result + dp(i+1, False, mask | (1 << right), j, False)) % MOD
        elif right == '?' and has_w == right:
            result = (result + dp(i+1, True, mask | (1 << right), j, True)) % MOD
        elif right == '?' and has_w != prev:
            result = (result + dp(i+1, True, mask | (1 << right), j, has_w)) % MOD
        elif right == '?' and has_w < prev and prev < right:
            result = (result + dp(i+1, True, mask | (1 << right), j, False)) % MOD
        else:
            result = (result + dp(i+1, True, mask | (1 << right), j, has_w)) % MOD

        memo[mask] = result % MOD
        return result % MOD

    memo = {}
    res = dp(0, True, 0, len(dominoes), False)

    return res % MOD

