import sys
from typing import List

def find_initial_sequence(matrix: List[List[int]]) -> List[List[int]]:
    n = len(matrix)
    initial_sequence = [0] * n
    for i in range(n):
        for j in range(n):
            if i == j:
                initial_sequence[i] = matrix[i][j]
    return initial_sequence

def update_matrix(matrix: List[List[int]], changes: List[List[int]]) -> None:
    n = len(matrix)
    for change in changes:
        p = change[0]
        new_values = change[1:]
        for i in range(n):
            matrix[p-1][new_values.index(new_values[0])] = n * n + 1
        for i, value in enumerate(new_values):
            matrix[i][p-1] = matrix[p-1][i] = value

def game(playa: str, matrix: List[List[int]], queries: List[List[int]]) -> List[List[int]]:
    initial_sequence = find_initial_sequence(matrix)

    results = [initial_sequence]
    for query in queries:
        updates = query[1:]
        update_matrix(matrix, [query[0], *updates])
        results.append(queries[0] + [initial_sequence[query[0]-1] for initial_sequence, _ in results])

    return results

def main():
    n, q = map(int, input().split())
    matrix = [list(map(int, input().split())) for _ in range(n)]
    queries = [[]]
    for _ in range(q):
        n, matrix, changes, queries = map(int, input().split()), [[]], [[]], [[]]
        changes = list(map(int, input().split()))
        if len(changes) == 1:
            queries[0].append(changes)
        else:
            queries[0].append([1, n] + changes)
    results = game(playa="", matrix=matrix, queries=queries)
    for res in results:
        print(*res)

