def bfs(start, exit, grid):
    queue = [start]
    visited = set([start])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    while queue:
        x, y = queue.pop(0)
        if (x, y) == exit:
            return True
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and grid[nx][ny] == '.' and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny))
    return False

def check_commands(commands, grid):
    rows, cols = len(grid), len(grid[0])
    for start in [(0, 0), (rows - 1, 0), (rows - 1, cols - 1), (0, cols - 1)]:
        if bfs(start, "E", grid):
