def power(a, b, m):
    if b == 0: 
        return 1 
    elif b % 2 == 0:  
        return power((a * a) % m, b // 2, m) 
    else: 
        return (a * power((a * a) % m, b // 2, m)) % m 

def F(N, A0, A1, A2, A3, Mod):
    return (A0 * power(N, Mod - 2, Mod) + 
            A1 * power(N**2, Mod - 2, Mod) * N + 
            A2 * power(N**3, Mod - 2, Mod) * N * N +
            A3 * power(N**4, Mod - 2, Mod) * N * N * N) % Mod

def calculate_multisets(test_cases):
    MOD = 1_000_000_007
    result = []

    for _ in range(test_cases):
        _, a0, a1, a2, a3 = map(int, input().split())
        S = int(input())
        result.append(pow((a0 + a1 * S + a2 * S**2 + a3 * S**3 + 1) * a0 % MOD, S, MOD))

    return result

T = int(input())
if T > 20:
    T = 20
print(*calculate_multisets(T), sep='\n')
