def getInitialAndAfterQueries(n, q, B, queries):
    initial_sequence = [0] * n
    for p, new_values in queries:
        if p == 1:
            initial_sequence[0] = new_values[0]
        elif p == n:
            initial_sequence[n-1] = new_values[-1]
        else:
            old_value = B[p-1][p-1]
            initial_sequence[p-1] = new_values[p-1] + 1

    after_queries = [[initial_sequence[i] - j if i + j < n else initial_sequence[i] for j in range(n)] for i in range(n)]

    return initial_sequence, after_queries

